import{_ as d,C as n,o as a,c as l,a3 as o,b as i,w as e,a as E,E as A,a4 as s}from"./chunks/framework.CWYzGJW1.js";const f=JSON.parse('{"title":"T1 是否需要訓練的判斷","description":"多數需求用提示與檢索就能解決, 微調應放在最後. 提示是把要求寫清楚, 檢索是讓模型先查自己的文件 (見 M4), 兩者都不必重新訓練模型.","frontmatter":{"description":"多數需求用提示與檢索就能解決, 微調應放在最後. 提示是把要求寫清楚, 檢索是讓模型先查自己的文件 (見 M4), 兩者都不必重新訓練模型."},"headers":[],"relativePath":"train/t1-decide.md","filePath":"train/t1-decide.md","lastUpdated":1793060541000}'),h={name:"train/t1-decide.md"};function B(p,t,g,c,m,b){const r=n("Mermaid");return a(),l("div",null,[t[1]||(t[1]=o('<h1 id="t1-是否需要訓練的判斷" tabindex="-1">T1 是否需要訓練的判斷 <a class="header-anchor" href="#t1-是否需要訓練的判斷" aria-label="Permalink to &quot;T1 是否需要訓練的判斷&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ○ 依情境</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-27</li><li>待查證: 「先提示, 再檢索, 最後才微調」的順序與決策流程為整理者歸納 (推論); 訓練時間依資料量, 硬體與設定差異很大, 本章不給數字, 需以小規模試跑實測; 顯示記憶體數字為 Unsloth 與 LLaMA-Factory 官方標示的最低值或估計值, 未實機驗證; 文中的類比為整理者所寫, 不代表技術上完全等同</li></ul></div><p><strong>結論</strong>: 多數需求用提示與檢索就能解決, 微調應放在最後. 提示是把要求寫清楚, 檢索是讓模型先查自己的文件 (見 <a href="/lanai-handbook/build/m4-retrieval">M4</a>), 兩者都不必重新訓練模型. 微調適合改變模型的「做法」, 例如固定的回答格式, 特定的語氣或分類規則; 若要讓模型「知道」新的事實, 檢索通常比微調可靠 (推論, 信心: 中). 決定微調之前, 先用 <a href="/lanai-handbook/build/m6-observability">M6</a> 的測試集量出提示與檢索的成績, 有了基準線, 才知道微調是否值得.</p><div class="tip custom-block"><p class="custom-block-title">本章常見名詞</p><table tabindex="0"><thead><tr><th>詞</th><th>意思</th></tr></thead><tbody><tr><td>提示 (prompt)</td><td>送給模型的指示與問題</td></tr><tr><td>檢索增強生成 (RAG)</td><td>回答前先從自己的文件找出相關段落, 再交給模型參考, 見 M4</td></tr><tr><td>微調 (fine-tuning)</td><td>拿自己的資料, 在現成模型上再訓練一次</td></tr><tr><td>監督式微調 (SFT)</td><td>用「問題與標準答案」成對的資料微調, 是最常見的微調方式</td></tr><tr><td>訓練集, 驗證集, 測試集</td><td>分別用來訓練, 訓練途中檢查, 以及訓練後驗收的三份資料, 彼此不可重疊</td></tr><tr><td>LoRA 與 QLoRA</td><td>只訓練一小組附加參數的微調方法, 原理見 <a href="/lanai-handbook/train/t2-finetune">T2</a></td></tr><tr><td>顯示記憶體 (VRAM)</td><td>顯示卡專用的記憶體, 決定能微調多大的模型</td></tr></tbody></table><p>完整詞彙見<a href="/lanai-handbook/ref/glossary">術語對照</a>.</p></div><h2 id="t1-1-提示-檢索與微調的選擇" tabindex="-1">T1.1 提示, 檢索與微調的選擇 <a class="header-anchor" href="#t1-1-提示-檢索與微調的選擇" aria-label="Permalink to &quot;T1.1 提示, 檢索與微調的選擇&quot;">​</a></h2><p>三種做法的差別, 可以想成帶新同事: 提示是把工作交代清楚, 檢索是給一份手冊讓對方隨時查, 微調則是送去受訓. 交代清楚就能做好的事, 不必送去受訓; 需要查資料的事, 給手冊比要求背下來可靠. 三者投入的資料與算力依序增加 (推論, 信心: 中).</p><p>OpenAI 的模型最佳化指南把流程排成: 先寫評測, 量出目前的表現作為基準線, 再調整提示; 指南表示, 調整提示的過程「可能就足以」得到很好的結果, 微調則是部分情境才需要 (來源: OpenAI 文件 Model optimization). 同一份指南列出微調相對於只用提示的好處: 能提供比單次請求上下文更多的範例, 提示可以縮短以降低成本與延遲, 可以讓模型穩定以特定格式回答, 也可以把小模型訓練成在特定工作上表現接近大模型 (來源同上). 這份指南也註明 OpenAI 正逐步結束其微調平台; 雲端微調服務本身也會變動, 這是考慮地端微調的原因之一 (來源同上).</p><p>微調比較擅長改變「怎麼回答」, 不擅長灌入新知識. LIMA 論文只用 1,000 筆精選的問答, 微調一個 65B 參數的模型, 就得到與部分商用模型相當的人工評比結果; 作者據此主張, 大型語言模型幾乎所有的知識都在預訓練階段學到, 微調主要教的是回答的格式與風格 (來源: Zhou 等人, LIMA: Less Is More for Alignment, 2023). 因此, 內部規章, 產品資料這類會更新的事實, 適合放進檢索; 公司慣用的報告格式, 固定的分類規則, 才適合考慮微調 (推論, 信心: 中).</p><p><strong>決策流程</strong> (整理者歸納, 推論, 信心: 中):</p>',9)),(a(),i(s,null,{default:e(()=>[A(r,{id:"mermaid-120",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E9%9C%80%E6%B1%82%3A%20%E5%85%88%E7%94%A8%20M6%20%E6%B8%AC%E8%A9%A6%E9%9B%86%E9%87%8F%E5%87%BA%E7%9B%AE%E5%89%8D%E7%9A%84%E6%88%90%E7%B8%BE%20(%E5%9F%BA%E6%BA%96%E7%B7%9A)%22%5D%20--%3E%20B%5B%22%E8%AA%BF%E6%95%B4%E6%8F%90%E7%A4%BA%20(%E6%8A%8A%E8%A6%81%E6%B1%82%2C%20%E7%AF%84%E4%BE%8B%2C%20%E6%A0%BC%E5%BC%8F%E5%AF%AB%E6%B8%85%E6%A5%9A)%22%5D%0A%20%20B%20--%3E%7C%22%E9%81%94%E6%A8%99%22%7C%20Z%5B%22%E7%B5%90%E6%9D%9F%22%5D%0A%20%20B%20--%3E%7C%22%E6%9C%AA%E9%81%94%E6%A8%99%22%7C%20C%7B%22%E5%95%8F%E9%A1%8C%E5%9C%A8%E3%80%8C%E4%B8%8D%E7%9F%A5%E9%81%93%E6%9F%90%E4%BA%9B%E4%BA%8B%E5%AF%A6%E3%80%8D%3F%22%7D%0A%20%20C%20--%3E%7C%22%E6%98%AF%22%7C%20D%5B%22%E5%8A%A0%E4%B8%8A%E6%AA%A2%E7%B4%A2%20(M4)%22%5D%0A%20%20D%20--%3E%7C%22%E9%81%94%E6%A8%99%22%7C%20Z%0A%20%20D%20--%3E%7C%22%E6%9C%AA%E9%81%94%E6%A8%99%22%7C%20G%5B%22%E5%85%88%E6%95%B4%E7%90%86%E8%B3%87%E6%96%99%20(T1.2)%2C%20%E6%88%96%E5%9B%9E%E5%88%B0%E6%8F%90%E7%A4%BA%22%5D%0A%20%20C%20--%3E%7C%22%E5%90%A6%2C%20%E5%95%8F%E9%A1%8C%E5%9C%A8%E6%A0%BC%E5%BC%8F%2C%20%E8%AA%9E%E6%B0%A3%E6%88%96%E5%88%A4%E6%96%B7%E8%A6%8F%E5%89%87%22%7C%20F%7B%22%E5%82%99%E5%A6%A5%201%2C000%20%E7%AD%86%E4%BB%A5%E4%B8%8A%E7%9A%84%E9%AB%98%E5%93%81%E8%B3%AA%E7%AF%84%E4%BE%8B%3F%22%7D%0A%20%20F%20--%3E%7C%22%E5%90%A6%22%7C%20G%0A%20%20F%20--%3E%7C%22%E6%98%AF%22%7C%20H%5B%22%E4%BC%B0%E7%AE%97%E9%A1%AF%E7%A4%BA%E8%A8%98%E6%86%B6%E9%AB%94%E8%88%87%E6%88%90%E6%9C%AC%20(T1.3)%22%5D%0A%20%20H%20--%3E%7C%22%E5%8F%AF%E8%A1%8C%22%7C%20I%5B%22%E5%BE%AE%E8%AA%BF%20(T2)%2C%20%E7%94%A8%E5%90%8C%E4%B8%80%E4%BB%BD%E6%B8%AC%E8%A9%A6%E9%9B%86%E9%A9%97%E6%94%B6%22%5D%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[E(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o('<p>「1,000 筆」取自 LIMA 的設定, 是說明量級的參考, 不是保證有效的門檻; 實際需要的筆數依工作而定 (推論, 信心: 低).</p><h2 id="t1-2-資料準備與品質檢查" tabindex="-1">T1.2 資料準備與品質檢查 <a class="header-anchor" href="#t1-2-資料準備與品質檢查" aria-label="Permalink to &quot;T1.2 資料準備與品質檢查&quot;">​</a></h2><p>微調資料的好壞, 直接決定微調後的模型像不像預期. 可以想成編寫受訓教材: 教材裡的錯誤示範, 學員也會照著學. 資料準備要回答四個問題: 要多少, 長什麼樣子, 品質怎麼檢查, 機密資料怎麼處理.</p><p><strong>資料量</strong>: LIMA 的結果顯示, 品質比數量重要, 1,000 筆精選範例就能改變模型的回答風格 (來源: LIMA 論文). 若筆數不多, 先把每一筆做對, 比大量蒐集良莠不齊的資料更有效 (推論, 信心: 中).</p><p><strong>格式</strong>: 微調工具多半讀取 JSONL 檔, 也就是每一行一筆 JSON 資料的文字檔. 以 MLX LM (在 Apple Silicon 上執行與微調模型的套件, 見 T2) 為例, 支援 <code>chat</code> (多輪對話), <code>tools</code> (工具呼叫), <code>completions</code> (提示與回答) 與 <code>text</code> (純文字) 四種格式; 資料目錄中必須有 <code>train.jsonl</code>, <code>valid.jsonl</code> 為選配, 有的話訓練途中會定期回報驗證損失 (來源: MLX LM 文件 LORA.md). 其他工具的格式各有規定, 見 <a href="/lanai-handbook/train/t2-finetune">T2</a>.</p><p><strong>品質檢查</strong> (整理者建議, 推論, 信心: 中):</p><ul><li>[ ] 每筆答案都經過熟悉業務的人核對, 沒有錯誤事實</li><li>[ ] 同類問題的答案格式一致, 不會一筆用條列, 一筆用段落</li><li>[ ] 刪除重複與幾乎重複的範例</li><li>[ ] 抽出一部分當驗證集, 並保留 M6 的測試集不放進訓練資料; 測試題若混進訓練資料, 驗收分數會偏高, 這種情形稱為資料汙染 (見 <a href="/lanai-handbook/know/k5-tools-agents">K5</a>)</li></ul><p><strong>個人資料與機密資料</strong>: 模型可能記住部分訓練資料, 並在回答中重現 (見 <a href="/lanai-handbook/know/k1-basics">K1.7 節</a>). 因此, 個人資料與機密資料要在進入訓練資料前就移除或遮蔽, 不能指望訓練後再過濾. Google 在 Gemma 3 的模型卡中說明, 預訓練資料以自動化方法過濾了部分個人資訊與其他敏感資料 (來源: Gemma 3 模型卡); 自行微調時也應比照, 在資料準備階段做過濾 (推論, 信心: 中). 微調後的模型檔本身也應視為與訓練資料同等級的機密, 依 <a href="/lanai-handbook/build/m3-model-intake">M3</a> 的方式管理存放權限 (推論, 信心: 中).</p><h2 id="t1-3-成本與時間估算" tabindex="-1">T1.3 成本與時間估算 <a class="header-anchor" href="#t1-3-成本與時間估算" aria-label="Permalink to &quot;T1.3 成本與時間估算&quot;">​</a></h2><p>微調的成本主要是顯示記憶體與時間. 顯示記憶體決定「能不能做」, 時間決定「要等多久, 電費多少」. 可以想成搬家: 卡車容量 (顯示記憶體) 不夠, 家具就裝不下; 容量夠了, 才談要跑幾趟 (時間).</p><p><strong>顯示記憶體</strong>: Unsloth (以較少顯示記憶體微調模型的訓練框架, 見 T2) 官方文件列出各模型大小的最低需求, 並說明這些是絕對最低值, 部分模型需要更多 (來源: Unsloth 文件 Unsloth Requirements):</p><table tabindex="0"><thead><tr><th>模型參數量</th><th>QLoRA (4 位元)</th><th>LoRA (16 位元)</th></tr></thead><tbody><tr><td>3B</td><td>3.5GB</td><td>8GB</td></tr><tr><td>8B</td><td>6GB</td><td>22GB</td></tr><tr><td>14B</td><td>8.5GB</td><td>33GB</td></tr><tr><td>27B</td><td>22GB</td><td>64GB</td></tr><tr><td>32B</td><td>26GB</td><td>76GB</td></tr><tr><td>70B</td><td>41GB</td><td>164GB</td></tr></tbody></table><p>LLaMA-Factory (提供網頁介面的微調框架, 見 T2) 的估計表另列出 7B 模型的全參數微調需要 120GB, 16 位元 LoRA 需要 16GB, 4 位元 QLoRA 需要 6GB, 並標示為估計值 (來源: LLaMA-Factory GitHub README). 兩份資料的 LoRA 數字不同, 原因是計算條件不同, 實際用量以試跑為準 (推論, 信心: 中). 對照 <a href="/lanai-handbook/know/k3-hardware">K3</a> 的硬體等級, 只有一張消費級顯示卡時, QLoRA 是較實際的選擇 (推論, 信心: 中). Unsloth 文件也提醒, 記憶體不足的錯誤常是批次大小設得太大, 建議先設為 1 至 3 (來源: Unsloth 文件).</p><p><strong>時間</strong>: 訓練時間取決於資料的 token 數, 訓練回合數 (epoch, 整份資料完整走過一次稱為一個回合), 模型大小與顯示卡, 公開資料無法給出適用各環境的數字. 建議先抽 5% 至 10% 的資料試跑一個回合, 記錄耗時, 再依比例推估完整訓練的時間 (整理者建議, 推論, 信心: 中).</p><p><strong>與雲端 API 的比較</strong>: 沿用<a href="/lanai-handbook/decide/tco">成本試算表</a>的框架, 在自架年成本中加入下列微調專屬項目:</p><table tabindex="0"><thead><tr><th>成本類別</th><th>公式</th><th>填入數字</th></tr></thead><tbody><tr><td>資料整理人時</td><td>整理與核對的小時數 x 時薪</td><td></td></tr><tr><td>訓練電費</td><td>試跑推估的訓練小時 x 平均功耗 (kW) x 電價 (元/度) x 每年重訓次數</td><td></td></tr><tr><td>驗收人時</td><td>每次以 M6 測試集比較與人工判讀的小時數 x 時薪 x 每年重訓次數</td><td></td></tr><tr><td>重訓頻率</td><td>基底模型改版, 或業務規則變更時都要重訓; 依過去一年的變更次數估計</td><td></td></tr></tbody></table><p>微調的成本不是一次性的. 基底模型每次改版, 附加的 LoRA 參數通常要重新訓練 (推論, 信心: 中); 若業務規則每季變動, 檢索只要更新文件, 微調則要重做一輪資料與驗收. 這是「事實放檢索, 做法才微調」的另一個理由.</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><ul><li><strong>評測先行, 提示可能已足夠, 微調的適用情境, OpenAI 微調平台逐步結束</strong>: <a href="https://developers.openai.com/api/docs/guides/model-optimization.md" target="_blank" rel="noreferrer">OpenAI 文件: Model optimization</a> (2026-10-27 擷取)</li><li><strong>1,000 筆精選範例, 65B 模型, 知識主要在預訓練階段學到</strong>: <a href="https://arxiv.org/abs/2305.11206" target="_blank" rel="noreferrer">Zhou 等人, LIMA: Less Is More for Alignment (arXiv 2305.11206)</a></li><li><strong>JSONL 資料格式, train.jsonl 與 valid.jsonl</strong>: <a href="https://github.com/ml-explore/mlx-lm/blob/main/mlx_lm/LORA.md" target="_blank" rel="noreferrer">MLX LM 文件: LORA.md</a></li><li><strong>預訓練資料過濾個人資訊與敏感資料</strong>: <a href="https://huggingface.co/google/gemma-3-270m" target="_blank" rel="noreferrer">Hugging Face 模型卡: google/gemma-3-270m (Gemma 3 系列共用的訓練資料說明)</a></li><li><strong>QLoRA 與 LoRA 的顯示記憶體最低值, 批次大小建議</strong>: <a href="https://www.unsloth.ai/docs/get-started/fine-tuning-for-beginners/unsloth-requirements" target="_blank" rel="noreferrer">Unsloth 文件: Unsloth Requirements</a> (2026-10-27 擷取)</li><li><strong>7B 模型各微調方式的估計記憶體</strong>: <a href="https://github.com/hiyouga/LlamaFactory" target="_blank" rel="noreferrer">LLaMA-Factory GitHub 儲存庫 (README)</a></li><li><strong>成本框架</strong>: <a href="/lanai-handbook/decide/tco">成本試算表</a>; <strong>測試集</strong>: <a href="/lanai-handbook/build/m6-observability">M6</a>; <strong>資料汙染</strong>: <a href="/lanai-handbook/know/k5-tools-agents">K5</a></li><li><strong>整理者判斷 (推論, 無外部來源)</strong>: 「事實放檢索, 做法才微調」的分工, 決策流程, 品質檢查清單, 試跑 5% 至 10% 推估時間的做法, 微調成本表的追加項目, 以及基底模型改版需重訓的判斷.</li><li><strong>文中的類比 (帶新同事, 編寫受訓教材, 搬家的卡車)</strong>: 整理者所寫, 無外部來源, 不應當作技術定義引用.</li></ul>',19))])}const u=d(h,[["render",B]]);export{f as __pageData,u as default};
